module.exports=[178984,549552,a=>{"use strict";a.s(["GUIDE",0,[{slug:"primi-passi",title:"Primi passi con 2Target",category:"inizia",icon:"solar:play-circle-bold",summary:"Le cose da fare la prima volta, in ordine, perché 2Target lavori da sola.",audience:"team",open:{path:"/",label:"Vai a Oggi"},keywords:["iniziare","configurare","setup","come si usa","partire"],blocks:[{p:"Nella pagina **Oggi**, finché non è tutto pronto, trovi il riquadro **Primi passi** con un pulsante **Fallo ora** per ogni voce. L'ordine consigliato è questo:"},{steps:["**Invio email** (amministratore): serve per i codici di accesso e gli avvisi. Impostazioni → Invio email → **Invia email di prova**.","**Chiavi di Meta** (amministratore): Impostazioni → Integrazioni. Senza, non si collegano Instagram e Facebook.","**Primo cliente**: in Oggi premi **Nuovo cliente**.","**Collega i social** del cliente dalla scheda Canali.","**Check-up** e **piano editoriale**: l'AI ti aiuta a capire cosa fare e a preparare i contenuti.","**Programma il primo post** dalla scheda del contenuto.","**Notifiche sul telefono** dal tuo Profilo e **invita i colleghi** da Utenti."]},{h:"Il lavoro di ogni giorno"},{p:"Apri **Oggi**: ti dice cosa esce nei prossimi giorni, cosa aspetta l'approvazione, cosa non è andato e quali contatti richiamare. Ogni riga porta dritta dove si risolve."},{tip:"In ogni scheda del cliente il pulsante con la **i** in alto a destra apre la pagina della guida che la spiega."}],related:["clienti","canali","piano-editoriale","notifiche"]},{slug:"oggi",title:"La pagina «Oggi»",category:"inizia",icon:"solar:home-angle-bold-duotone",summary:"Cosa trovi nella prima pagina e come usarla ogni mattina.",audience:"team",open:{path:"/",label:"Apri Oggi"},keywords:["home","dashboard","cruscotto","da fare","attività"],blocks:[{p:"In alto quattro numeri: **In uscita in 7 giorni**, **Da approvare**, **Da sistemare** e **KPI fuori obiettivo**. Sotto, i riquadri con le cose da fare:"},{list:["**In uscita nei prossimi 7 giorni**: i contenuti programmati, cliente per cliente.","**Da sistemare**: post non usciti, collegamenti scaduti, check-up fermi e problemi del sito.","**Lead da contattare**: i contatti nuovi, in rosso quelli che aspettano da più di un giorno.","**Usciti nelle ultime 24 ore**, **Da approvare**, **Materiale da chiedere ai clienti**, **KPI fuori obiettivo**."]},{p:"In fondo l'elenco **Clienti** con la prossima uscita, i contenuti da approvare e i KPI in linea. **Nuovo cliente** crea un cliente: bastano il nome e, se li hai, settore, sito, partita IVA e città."}],related:["primi-passi","clienti"]},{slug:"clienti",title:"Clienti",category:"clienti",icon:"solar:users-group-rounded-bold",summary:"Creare un cliente e muoversi tra le sue schede.",audience:"team",keywords:["nuovo cliente","anagrafica","schede","selettore"],blocks:[{steps:["In **Oggi** premi **Nuovo cliente**.","Scrivi **Ragione sociale o nome** (gli altri campi sono facoltativi ma aiutano l'AI del check-up).","Il cliente compare nel menu a sinistra e nell'elenco Clienti."]},{p:"Ogni cliente ha le sue schede, nell'ordine del lavoro: **Panoramica** · Strategia (**Check-up**, **Brand**, **Concorrenti**) · Contenuti (**Idee**, **Piano editoriale**) · Risultati (**KPI**, **Lead**, **SEO**) · **Canali** e **Profili**."},{tip:"Il selettore **Cliente** in alto cambia cliente restando nella stessa scheda: comodo per controllare i piani di tutti, uno dopo l'altro."}],related:["panoramica-cliente","funzioni"]},{slug:"panoramica-cliente",title:"Panoramica del cliente",category:"clienti",icon:"solar:home-angle-bold-duotone",summary:"Il riassunto del cliente, i passi da fare e le opzioni (report, avvisi, funzioni).",audience:"team",open:{clientTab:"",label:"Panoramica"},keywords:["riepilogo","opzioni cliente","report","avvisi"],blocks:[{p:"In alto i passi consigliati (check-up, social, piano, KPI) e i numeri del mese: **Pubblicati questo mese**, **Lead questo mese**, **KPI in linea**. Poi le prossime uscite, i social collegati, i KPI e lo stato di check-up e piano."},{h:"Report, avvisi e approvazione"},{p:"Qui accendi il **report mensile automatico** e l'**avviso al cliente quando un post esce**, scrivendo l'email del cliente. Da **Report del mese** apri il report (PDF e video) di un mese a scelta."},{h:"Funzioni per questo cliente"},{p:"In fondo puoi spegnere le sezioni che con questo cliente non usate: spariscono dalle sue schede."}],related:["report-mensile","funzioni"]},{slug:"check-up",title:"Check-up con l'AI",category:"clienti",icon:"solar:notes-bold-duotone",summary:"L'analisi iniziale (o periodica) del cliente: cosa va, cosa no, cosa fare.",audience:"team",open:{clientTab:"checkup",label:"Check-up"},keywords:["analisi","audit","ai","report","swot","domande","ricognizione","consegna"],blocks:[{p:"Il check-up studia il cliente online (sito, social, concorrenti), ti fa qualche domanda e scrive un report completo con punti di forza, problemi, concorrenti, obiettivi e azioni."},{steps:["Apri **Check-up** → **Nuovo check-up**. Controlla i dati del cliente, i **Profili social** (uno per riga) e scrivi gli **Appunti dell'incontro**.","Scegli il modello (il costo stimato è scritto accanto) e premi **Avvia la ricognizione**: in 2-4 minuti arrivano le domande. Puoi chiudere la pagina intanto.","Rispondi a **Domande per te** (quelle lasciate vuote valgono «non noto») e premi **Avvia ricerca e scrittura** (5-12 minuti).","Rileggi le 8 sezioni: ognuna si corregge a mano o con **Rivedi con l'AI**, poi **Salva sezione**.","Porta lo stato su **Consegnato** e premi **Aggiorna**: il cliente può vedere il report."]},{h:"Dopo la consegna"},{p:"**Prepara la base di lavoro** propone in 1-3 minuti KPI, canali, rubriche, idee e una bozza del primo mese di piano, senza duplicare ciò che esiste già."},{tip:"Se l'AI si ferma per un errore premi **Riprendi**: riparte da dove era. Chi preferisce può scegliere **Compila a mano**."},{warn:"Un check-up consegnato è in sola lettura: per modificarlo riportalo «In revisione»."}],related:["piano-editoriale","kpi","consumi-ai"]},{slug:"brand",title:"Brand e studio grafico",category:"clienti",icon:"solar:palette-bold",summary:"Logo, colori e font del cliente, e la revisione delle grafiche con l'AI.",audience:"team",open:{clientTab:"brand",label:"Brand"},keywords:["logo","colori","palette","font","grafica","revisione","canva"],blocks:[{p:"Il **Brand kit** raccoglie l'identità del cliente: serve a te, ai grafici e all'AI quando prepara brief e testi."},{steps:["**Carica logo**: togli i margini vuoti e scegli la parte da usare come icona, poi **Usa questo logo**.","Aggiungi i colori (**Aggiungi colore**) e i font (**Aggiungi font**, con l'alternativa su Canva).","Descrivi tono visivo, stile delle foto, regole, cosa fare e cosa evitare. Oppure premi **Proponi con l'AI**.","Premi **Salva brand kit**."]},{h:"Revisione grafica"},{p:"Trascina una grafica (PNG, JPG o WebP fino a 5 MB): l'AI la valuta su leggibilità, contrasto, allineamento, rispetto del brand, testo e formato, e risponde **Pronta**, **Piccole correzioni** o **Da rifare**, con cosa cambiare."}],related:["scheda-contenuto"]},{slug:"idee",title:"Idee",category:"contenuti",icon:"solar:atom-bold-duotone",summary:"La bacheca delle idee per i contenuti, dal primo spunto al piano.",audience:"team",open:{clientTab:"idee",label:"Idee"},keywords:["bacheca","kanban","spunti","brainstorming"],blocks:[{p:"Le idee scorrono in quattro colonne: **Idee** → **In sviluppo** → **Approvate** → **Nel piano**. Si spostano trascinandole (o con **Sposta**)."},{list:["**Nuova idea**: titolo, descrizione, formato e fase del funnel.","**Metti nel piano**: scegli il piano e premi **Crea la scheda**: diventa un contenuto da preparare.","**Non convince** o **Scarta** per le idee da lasciar perdere."]},{tip:"Le idee nate dal check-up o dall'analisi SEO hanno un'etichetta che lo indica."}],related:["piano-editoriale"]},{slug:"piano-editoriale",title:"Piano editoriale",category:"contenuti",icon:"solar:calendar-date-bold",summary:"Creare il piano (a mano, con l'AI o da un file) e portarlo fino alla pubblicazione.",audience:"team",open:{clientTab:"piano",label:"Piano editoriale"},keywords:["calendario editoriale","contenuti","genera","importa","excel","word","programma il piano","scarica"],blocks:[{h:"Tre modi per crearlo"},{list:["**Nuovo piano**: nome, data di inizio, quanti contenuti a settimana, piattaforme e brief.","**Genera con l'AI**: parte dal check-up, ti fa qualche domanda e in 3-8 minuti prepara il piano in bozza.","**Importa da file**: Excel, Word, PDF o CSV. 2Target legge le righe, tu le correggi e le importi come bozze."]},{h:"Dalla bozza all'uscita"},{steps:["Nella vista **Calendario** o **Elenco** apri ogni contenuto e completalo (testo, foto o video).","Fallo approvare: dal team o dal cliente con il link di approvazione.","Premi **Programma il piano**: la finestra mostra le schede **Pronte da programmare**, quelle **Da sistemare** (con il motivo) e quelle **Già programmate**. Conferma con **Programma n schede**."]},{p:"**Controlli sul piano** segnala cosa manca (date, formati, equilibrio tra i tipi di contenuto). **Scarica Word** esporta il piano da mandare al cliente."},{tip:"Il riquadro **Da riproporre** suggerisce i contenuti usciti da almeno 3 mesi che hanno funzionato: **Riproponi** ne crea una copia in bozza."}],related:["scheda-contenuto","approvazione-cliente","pubblicare","idee"]},{slug:"approvazione-cliente",title:"Far approvare i contenuti al cliente",category:"contenuti",icon:"solar:check-circle-bold",summary:"Un link da mandare al cliente: approva o chiede modifiche senza account.",audience:"team",open:{clientTab:"piano",label:"Piano editoriale"},keywords:["approvazione","link","cliente approva","modifiche","ok cliente"],blocks:[{p:"Si attiva per cliente: **Panoramica del cliente → Approvazione del cliente obbligatoria** (oppure dal piano, in **Approvazione cliente**). Accesa, ogni post creato con «Crea post» o nello Studio aspetta l'ok del cliente; appena approvato **esce da solo** alla data e sui profili scelti. Spenta, i post escono quando li programmi."},{steps:["Nel piano apri **Approvazione cliente** e accendi l'interruttore.","**Manda n** porta in approvazione le bozze complete dei prossimi 30 giorni.","**Crea il link da mandare al cliente** e mandaglielo (vale 60 giorni).","Il cliente scrive il suo nome e per ogni contenuto preme **Approva** o **Chiedi modifiche** con un commento.","Le risposte compaiono nella scheda del contenuto, in **Risposte del cliente**."]},{warn:"Spegnendo l'approvazione, i link già mandati smettono di funzionare."},{tip:"Se il cliente approva dopo la data prevista, il post non esce da solo: chi l'aveva preparato riceve un avviso per scegliere una nuova data."}],related:["piano-editoriale"]},{slug:"scheda-contenuto",title:"La scheda del contenuto",category:"contenuti",icon:"solar:file-text-bold",summary:"Tutto quello che serve per un post: testi, riprese, produzione, sponsorizzata, file.",audience:"team",keywords:["post","caption","hashtag","script","reel","carosello","storia","primo commento","coautori","sponsorizzata","brief grafico"],blocks:[{p:"In alto lo stato: **Bozza → Da approvare → Approvato → Pubblicato** (o **Annullato**). L'etichetta **Da salvare** ricorda le modifiche non salvate: premi **Salva**."},{list:["**Testo**: titolo interno, frase d'apertura, testo del post, hashtag, primo commento, coautori Instagram, sede, invito all'azione e dove porta.","**Script e riprese**: idea di layout, voiceover, testo a schermo, musica e l'elenco delle clip da girare.","**Produzione**: a che punto è. **Serve materiale dal cliente** lo fa comparire in Oggi.","**Sponsorizzata**: obiettivo, budget e giorni, se il post andrà sponsorizzato.","**Note**: note interne e link al post pubblicato."]},{p:"A destra: data e ora (con gli **Orari migliori** calcolati sui post del cliente), formato, social principale, **Pubblica anche su**, e i **Controlli** che dicono cosa manca."},{p:"Sotto: l'**Anteprima** del post, il **Brief grafico** per il grafico, la **Revisione grafica** e il riquadro per **caricare i file e pubblicare**."},{tip:"**Sempre valido** segnala un contenuto che non invecchia: dopo 3 mesi 2Target lo propone da riproporre."}],related:["pubblicare","piano-editoriale","sponsorizzate"]},{slug:"calendario",title:"Calendario di tutti i clienti",category:"contenuti",icon:"solar:calendar-date-bold",summary:"Le uscite di tutti i clienti in un unico calendario, con i filtri.",audience:"team",open:{path:"/calendario",label:"Apri il calendario"},keywords:["agenda","uscite","mese","settimana"],blocks:[{p:"Viste **Mese**, **Settimana** ed **Elenco**. Filtra per formato, stato e tipo di uscita, e scegli quali clienti vedere."},{p:"Le uscite non riuscite hanno il bordo rosso; in alto l'avviso conta i contenuti non usciti. Un contenuto senza icona di uscita non verrà pubblicato da 2Target (va programmato dalla scheda)."}],related:["piano-editoriale","pubblicare"]},{slug:"profili-social",title:"Creare e completare i profili social",category:"canali",icon:"solar:user-id-bold",summary:"Profili Facebook, Instagram, TikTok e scheda Google: controlli e testi pronti.",audience:"team",open:{clientTab:"profili",label:"Profili"},keywords:["bio","creare profilo","pagina facebook","scheda google","completezza"],blocks:[{p:"**Controlla i collegati** misura quanto sono completi Pagina Facebook e profilo Instagram, e indica cosa correggere (alcune cose si correggono direttamente da qui)."},{p:"Per i profili che mancano: segui i passi di **Come si crea**, apri la creazione e usa **Prepara i testi con l'AI** per avere nome, nomi utente, bio, descrizioni, storie in evidenza e hashtag pronti da copiare."}],related:["canali"]},{slug:"kpi",title:"KPI: gli obiettivi da misurare",category:"risultati",icon:"solar:chart-square-outline",summary:"Fissare gli obiettivi e leggere il semaforo.",audience:"tutti",open:{clientTab:"kpi",label:"KPI"},keywords:["obiettivi","target","semaforo","misure","risultati","metriche"],blocks:[{p:"I KPI sono gli obiettivi del marketing (follower, copertura, contatti, costo per contatto…), divisi in **Organico**, **Sponsorizzato** e **Business**."},{list:["**In linea** (verde): raggiunto almeno il 90% dell'obiettivo.","**Da migliorare** (giallo): tra il 60% e il 90%.","**Sotto obiettivo** (rosso): sotto il 60%.","Per i costi vale il contrario: più basso è, meglio è."]},{p:"Con **Nuovo KPI** scegli metrica, canale, obiettivo e punto di partenza. Se il canale è collegato, la misura si aggiorna da sola ogni notte; altrimenti si inserisce con **Aggiungi misura**."}],related:["lead","report-mensile"]},{slug:"lead",title:"Lead: i contatti arrivati",category:"risultati",icon:"solar:user-plus-bold",summary:"Raccogliere i contatti, seguirli fino al cliente e calcolare quanto rende il marketing.",audience:"tutti",open:{clientTab:"lead",label:"Lead"},keywords:["contatti","pipeline","funnel","roi","roas","costo per lead","modulo","preventivo"],blocks:[{p:"In alto i numeri del periodo: lead, costo per lead, nuovi clienti, costo di acquisizione, ricavi e ritorno (ROI / ROAS), poi funnel, andamento, risultati per campagna e per fonte, e i motivi per cui si perdono."},{h:"La pipeline"},{p:"I contatti passano per **Nuovi → Contattati → Qualificati → Preventivo → Clienti** (o **Persi**): si spostano trascinandoli. Per un cliente vinto si indica il valore, per uno perso il motivo."},{h:"Raccolta automatica"},{list:["**Crea indirizzo di raccolta**: i moduli del sito mandano i contatti direttamente in 2Target (con **Copia esempio modulo**).","I contatti dei moduli delle inserzioni Meta arrivano da soli, ogni 15 minuti.","La fonte si riconosce dai link con UTM."]},{p:"In **Costi di marketing** inserisci le spese del mese: servono per calcolare costo per lead e ritorno."},{tip:"Un lead nuovo arriva anche per email e, se attive, come notifica sul telefono."}],related:["sponsorizzate","kpi","notifiche"]},{slug:"seo",title:"SEO e sito",category:"risultati",icon:"eva:search-fill",summary:"Come il sito viene trovato su Google e cosa migliorare.",audience:"tutti",open:{clientTab:"seo",label:"SEO"},keywords:["google","search console","analytics","posizione","ricerche","pagespeed","recensioni","scheda google"],blocks:[{p:"Con Google collegato trovi: clic, impressioni, CTR e posizione media da Search Console (ultimi 28 giorni rispetto ai 28 prima), le ricerche e le pagine migliori, le ricerche con il nome del brand, la scheda Google (visualizzazioni, chiamate, recensioni), Google Ads, Analytics e la velocità del sito."},{p:"**Analisi del mese con l'AI** riassume cosa è cambiato e propone le priorità con impatto e sforzo; con **Crea le idee** le trasforma in idee per i contenuti. Parte da sola ogni mese."},{tip:"**Quasi in prima pagina** elenca le ricerche per cui il sito è vicino alla prima pagina: spesso basta poco per guadagnare molti clic."}],related:["canali","idee"]},{slug:"sponsorizzate",title:"Sponsorizzate e moduli contatti",category:"pubblicazione",icon:"solar:wad-of-money-bold",summary:"Avviare campagne su Meta, raccogliere contatti e tenere sotto controllo la spesa.",audience:"team",open:{path:"/sponsorizzate",label:"Apri Sponsorizzate"},keywords:["ads","inserzioni","campagna","budget","meta ads","lead ads","rifatturare","spesa"],blocks:[{p:"Prima, in **Canali** del cliente → **Sponsorizzate Meta**, scegli chi paga (il cliente o Golduck con rifatturazione), l'account pubblicitario e il **tetto di spesa mensile**."},{h:"Sponsorizzare un post uscito"},{p:"Nella scheda del contenuto, dopo l'uscita: **Sponsorizza** → obiettivo, budget, durata, zona ed età → **Continua** → **Avvia la sponsorizzata**."},{h:"Una campagna completa"},{steps:["Vai in **Sponsorizzate** → **Nuova campagna**.","Scegli cliente, contenuto e foto/video.","Scegli l'obiettivo (Contatti, Traffico, Notorietà, Interazione) e dove mostrarla.","Scrivi i testi, scegli pubblico e budget, poi **Continua** e **Avvia la campagna**."]},{p:"Per l'obiettivo **Contatti** serve un **modulo contatti** (con l'informativa privacy del cliente): i contatti finiscono direttamente nei Lead."},{p:"La pagina Sponsorizzate mostra la spesa del mese, i **Consigli** (cosa sta andando male, dove investire), la spesa giorno per giorno e **Da rifatturare** con **Esporta CSV**."},{warn:"Ogni avvio chiede di confermare la spesa: 2Target non supera mai il tetto mensile del cliente."}],related:["lead","scheda-contenuto"]},{slug:"consumi-ai",title:"Consumi AI",category:"amministrazione",icon:"solar:atom-bold-duotone",summary:"Quanto si spende per l'intelligenza artificiale e come restare nel budget.",audience:"team",open:{path:"/consumi-ai",label:"Apri Consumi AI"},keywords:["costi","budget","spesa ai","anthropic","claude"],blocks:[{p:"La pagina mostra la spesa del mese (in euro), la previsione a fine mese, la spesa per cliente, le ultime chiamate e un'analisi (fase più costosa, costo medio di un check-up)."},{p:"I limiti si fissano in **Impostazioni** → **Limiti e blocchi automatici**: budget mensile, soglia di avviso, tetto per check-up e per cliente. Superato il budget, le funzioni AI si fermano finché il mese non cambia o il limite non viene alzato."}],related:["check-up","impostazioni"]},{slug:"utenti-e-ruoli",title:"Utenti e ruoli",category:"amministrazione",icon:"solar:user-rounded-bold",summary:"Invitare colleghi e clienti, e decidere chi può fare cosa.",audience:"admin",open:{path:"/utenti",label:"Apri Utenti"},keywords:["invitare","accesso","permessi","viewer","cliente","pubblicare","disattivare"],blocks:[{list:["**Super admin**: il titolare, può tutto e non si modifica.","**Administrator**: gestisce utenti, impostazioni e limiti AI.","**User**: lavora sui clienti. Pubblica sui social solo se lo abiliti.","**Viewer**: il cliente. Vede solo KPI, Lead e SEO dei clienti che gli assegni, in sola lettura."]},{steps:["**Nuovo utente**: nome, email e ruolo (per un Viewer scegli i clienti che può vedere).","Lascia **Invia l'email di invito**: riceve il link per entrare.","Per gli User accendi **Pubblica sui social** se devono pubblicare o collegare account."]},{p:"Non ci sono password: si entra con un codice via email. Per togliere l'accesso a qualcuno premi **Disattiva** (si può riattivare)."}],related:["accesso-e-sicurezza"]},{slug:"impostazioni",title:"Impostazioni",category:"amministrazione",icon:"solar:settings-bold",summary:"Cosa si regola nelle Impostazioni e come ci si entra.",audience:"admin",open:{path:"/impostazioni",label:"Apri Impostazioni"},keywords:["configurazione","email","smtp","microsoft","simulazione","pubblicazione reale","limiti","metodologia"],blocks:[{p:"Per sicurezza le Impostazioni chiedono un codice nuovo via email (**Inviami il codice**), valido 15 minuti. **Chiudi le Impostazioni** le richiude subito."},{list:["**Stato del sistema**: semafori e backup.","**Funzioni**: cosa si vede nei menu.","**Invio email**: servizio di posta (Microsoft 365 consigliato) e **Invia email di prova**.","**Integrazioni**: chiavi delle app e l'interruttore **Pubblicazione reale sui social** (spento = simulazione).","**Limiti e blocchi automatici** per l'AI.","**Metodologia** del check-up e del piano: le istruzioni che segue l'AI, con le versioni salvate."]}],related:["stato-del-sistema","funzioni","integrazioni"]},{slug:"accesso-e-sicurezza",title:"Accesso e doppio fattore",category:"inizia",icon:"solar:shield-check-bold",summary:"Entrare con il codice via email, il doppio fattore e i codici di recupero.",audience:"tutti",open:{path:"/profilo",label:"Apri il Profilo"},keywords:["login","codice","password","2fa","autenticazione","recupero","microsoft"],blocks:[{steps:["Scrivi la tua email e premi **Inviami il codice**.","Inserisci il codice di 6 cifre arrivato per email e premi **Entra**.","Su un dispositivo tuo puoi spuntare **Ricordami su questo dispositivo** (30 giorni)."]},{p:"I colleghi Golduck possono anche usare **Accedi con Microsoft**."},{h:"Doppio fattore"},{p:"Dal **Profilo** → **Attiva il doppio fattore**: inquadri il QR con un'app (es. Google Authenticator), scrivi il codice e confermi. Conserva i **codici di recupero**: sono mostrati una volta sola e servono se perdi il telefono."},{warn:"Non usare «Ricordami» su computer condivisi."}],related:["utenti-e-ruoli"]},{slug:"audit",title:"Registro attività ed errori",category:"amministrazione",icon:"solar:file-text-bold",summary:"Il registro di chi ha fatto cosa, e degli errori.",audience:"team",open:{path:"/audit",label:"Apri il registro"},keywords:["registro","log","storico","errori","chi ha fatto"],blocks:[{p:"Ogni azione importante (accessi, modifiche, pubblicazioni, collegamenti, errori) resta registrata con chi, quando e cosa è cambiato. Gli amministratori vedono tutto, gli altri le proprie voci."},{p:"Si filtra per periodo, categoria, utente e cliente, e si scarica per Excel. Per segnalare un errore a un tecnico basta dargli il numero della voce."}],related:["problemi-frequenti"]},{slug:"per-il-cliente",title:"Guida per il cliente",category:"inizia",icon:"solar:chart-square-outline",summary:"Cosa trovi nella tua area: obiettivi, contatti e andamento del sito.",audience:"tutti",keywords:["cliente","viewer","area riservata","risultati"],blocks:[{p:"Nella tua area trovi, sempre aggiornati ogni notte:"},{list:["**KPI**: gli obiettivi concordati, con il semaforo (verde = in linea).","**Lead**: i contatti arrivati e a che punto sono.","**SEO**: come il sito viene trovato su Google."]},{p:"Se hai più attività, scegli quella da vedere dal selettore **Cliente** in alto. Per qualsiasi dubbio scrivi al tuo consulente Golduck."}],related:["kpi","lead","seo"]},{slug:"problemi-frequenti",title:"Domande frequenti",category:"problemi",icon:"solar:info-circle-bold",summary:"Le risposte rapide ai dubbi e ai problemi più comuni.",audience:"team",keywords:["faq","aiuto","non funziona","problema","errore"],blocks:[{h:"Il post non è uscito"},{p:"Apri la scheda: nel riquadro delle uscite c'è il motivo. Sistemalo (es. ricollega il profilo, ricarica il video) e premi **Riprova**: 2Target controlla prima che il post non sia già online."},{h:"Non vedo una sezione nel menu"},{p:"Forse è stata spenta in **Impostazioni → Funzioni** o per quel cliente nella sua Panoramica. Oppure il tuo ruolo non la prevede."},{h:"Non riesco a pubblicare o a collegare un account"},{p:"Pubblicano e collegano gli amministratori e gli User abilitati a **Pubblica sui social** (in Utenti). La scheda deve essere **Approvata** e salvata."},{h:"Il codice di accesso non arriva"},{p:"Controlla lo spam e attendi un minuto, poi **Inviami un nuovo codice**. Se non arriva a nessuno, un amministratore controlli **Invio email** nelle Impostazioni."},{h:"L'AI non parte"},{p:"Può essere finito il budget del mese: guarda **Consumi AI**. Un amministratore può alzare il limite nelle Impostazioni."},{h:"Il post è uscito in privato su TikTok"},{p:"Finché TikTok non approva l'app di Golduck, i post escono visibili solo al proprietario: è una regola di TikTok."}],related:["problemi-collegamento","pubblicare","funzioni"]},{slug:"canali",title:"Collegare i social del cliente",category:"canali",icon:"eva:link-2-fill",summary:"Come collegare Instagram, Facebook, TikTok, LinkedIn, Google, Threads e Pinterest, una volta sola.",audience:"team",open:{clientTab:"canali",label:"Canali"},keywords:["collegare","instagram","facebook","tiktok","linkedin","google","youtube","threads","pinterest","account","login","ricollega"],blocks:[{p:"Collegare un social serve a due cose: 2Target **legge i dati** (follower, post, statistiche) e **pubblica i post** all'ora programmata. Si fa una volta per cliente."},{h:"Come si collega"},{steps:["Apri il cliente e vai nella scheda **Canali**.","In **Collega gli account** premi **Collega** sulla piattaforma (es. «Collega Meta»): si apre la pagina di accesso di Meta, Google, TikTok, ecc.","Il cliente (o chi gestisce il suo profilo) fa l'accesso e conferma i permessi. Se siete insieme, può farlo dal suo telefono.","Tornati in 2Target, nella finestra «Quali canali sono di questo cliente?» spunta **solo** le sue pagine e i suoi profili e premi **Collega e scarica i dati**.","La prima lettura dei dati parte subito; poi 2Target aggiorna tutto ogni notte."]},{h:"Quale collegamento scegliere"},{list:["**Meta**: Pagine Facebook e profili Instagram collegati a una Pagina. È il collegamento più completo (anche sponsorizzate e moduli contatti).","**Instagram senza Facebook**: per i profili professionali che non hanno una Pagina Facebook.","**Google**: Search Console, Analytics, scheda Google, Google Ads e YouTube.","**TikTok**, **LinkedIn** (pagina aziendale), **Threads** e **Pinterest** (ogni bacheca è un canale a sé)."]},{warn:"Un profilo può appartenere a un solo cliente: se è già collegato a un altro, 2Target lo rifiuta. È una protezione contro i post pubblicati sul cliente sbagliato."},{tip:"Se un collegamento diventa rosso («da ricollegare»), di solito la password è cambiata o il permesso è stato tolto: premi di nuovo **Collega** e rifai l'accesso. I dati già raccolti restano."},{p:"Sito web e profili senza collegamento si possono aggiungere a mano con **Aggiungi sito o profilo**: del sito 2Target controlla velocità (PageSpeed), certificato e scadenza del dominio."}],related:["pubblicare","problemi-collegamento","integrazioni"]},{slug:"studio",title:"Lo Studio: creare un post con l'AI",category:"pubblicazione",icon:"solar:atom-bold-duotone",summary:"Testo, grafica e video a quattro mani con l'AI, in quattro passi e tutto in una schermata.",audience:"team",keywords:["studio","ai","intelligenza artificiale","grafica","carosello","video","montaggio","reel","musica","immagine ai","nano banana","versioni","chat"],blocks:[{p:"Premi **Crea post**, scegli il cliente e **Con l'AI**, poi scrivi cosa ti serve (es. «reel di 15 secondi sulla promo di ottobre, tono caldo»). Lo Studio si apre e l'AI prepara una prima versione."},{h:"Come è fatto"},{list:["**A sinistra la chat**: chiedi modifiche a parole («accorcia il testo», «fai 4 slide», «scritta finale più grande»). Ogni risposta dell'AI è una nuova versione.","**Al centro il passo** su cui lavori; **a destra l'anteprima** del post come apparirà.","**In alto il pulsante del prossimo passo**: dice sempre cosa fare dopo (Salva, Esporta nel post, Crea il video…).","**Versione n** in alto: chi l'ha fatta (tu o l'AI) e il ritorno a una versione precedente con **Torna a questa**."]},{h:"I quattro passi"},{steps:["**Contenuto**: titolo, testo, hashtag, formato e i file. Con **Immagine AI** crei un'immagine nuova o modifichi una foto del cliente (sfondo, luce, ambientazione).","**Grafica o video** (facoltativo). **Grafica**: pagine e livelli con colori e logo del cliente, poi **Esporta nel post**. **Video**: scegli i pezzi dei video, aggiungi scritte e musica, poi **Crea il video** (lo compone il server in pochi secondi).","**Quando e dove**: profili, data e ora (anche gli orari migliori), poi **Programma** o **Pubblica ora**. Se il cliente deve approvare, il pulsante diventa **Manda in approvazione**.","**Uscite**: dove è programmato o uscito il post, con eventuali errori."]},{tip:"Il post esce con l'ultima cosa esportata: la grafica oppure il video, mai entrambi. Le foto e i video usati restano nel **materiale** e non escono da soli."},{h:"Il montaggio video"},{list:["**Timeline** con tre tracce: **Video** (le clip in fila), **Scritte** e **Audio**. Il cursore rosso segna il punto: clicca sul righello per spostarlo.","**Trascina** un blocco per spostarlo (una clip cambia posto nella fila); **tira i bordi** per accorciarlo o allungarlo. I blocchi si agganciano ai bordi degli altri e al cursore.","**Dividi** (tasto S) taglia la clip o il brano selezionato al cursore; **Duplica** lo copia; **Elimina** (Canc) lo toglie. Spazio fa partire e fermare l'anteprima.","**Musica**: carica un tuo brano (MP3, M4A) oppure **Cerca nelle librerie musicali**. Il brano entra nella traccia audio al cursore, con il suo volume."]},{p:"Le librerie gratuite (Openverse, che raccoglie Jamendo, Freesound, ccMixter e Wikimedia; Jamendo con il client ID in Impostazioni) mostrano solo brani utilizzabili per i clienti: **CC0** (liberi) e **CC BY**. Con CC BY lo Studio ti chiede di aggiungere i crediti al testo del post: è la condizione della licenza."},{warn:"La musica di Instagram e TikTok non si può aggiungere da strumenti esterni: si sceglie nell'app al momento di pubblicare. Per i brani tuoi, usa solo quelli di cui hai i diritti per i social."},{p:"La spesa dell'AI di ogni progetto compare sotto il titolo; le immagini AI hanno un loro tetto mensile in Impostazioni → Limiti AI."}],related:["pubblicare","approvazione-cliente"]},{slug:"pubblicare",title:"Pubblicare e programmare i post",category:"pubblicazione",icon:"custom:send-fill",summary:"Dalla scheda approvata al post online: subito o all'ora scelta, su uno o più profili.",audience:"team",keywords:["crea post","nuovo post","programmare","pubblicazione","post","uscita","orario","simulazione","riprova","errore","reel","carosello","storia"],blocks:[{p:"2Target pubblica da sola su Facebook, Instagram, TikTok, LinkedIn, Threads, Pinterest, YouTube (Shorts) e sulla scheda Google. Pubblica solo schede **approvate**."},{h:"Il modo più veloce: «Crea post»"},{p:"**Crea post** in alto chiede il cliente e il modo: **Semplice** (i tre passi qui sotto), **Avanzato** (apre una scheda completa vuota) o **Con l'AI** (apre lo Studio: vedi l'articolo dedicato)."},{steps:["Premi **Crea post** in alto, scegli il cliente e il modo **Semplice**.","**Dove**: i profili collegati del cliente sono già spuntati (togli quelli che non servono).","**Cosa**: scrivi il testo (oppure scrivi in due parole l'idea e premi **Scrivi con l'AI**) e trascina foto o video. Un video diventa un reel, più file un carosello. A destra vedi l'anteprima.","**Quando**: scegli data e ora (anche dagli orari migliori suggeriti) oppure **Pubblica ora**, poi **Programma**."]},{p:"Il post entra da solo nel piano editoriale in corso. Se per quel cliente è obbligatoria l'approvazione, o se non sei abilitato a pubblicare, va in «Da approvare» ed **esce da solo dopo l'ok**, alla data e sui profili scelti. Per TikTok, sponsorizzate, script e riprese usa la scheda completa."},{h:"Dalla scheda completa"},{steps:["Apri la scheda del contenuto (dal piano editoriale o dal calendario).","Carica foto o video nella scheda e controlla testo e hashtag. L'anteprima mostra come apparirà.","Porta la scheda in **Approvato** (in alto): si salva da sola.","Nel riquadro **Pubblica sui profili del cliente** spunta i profili su cui deve uscire.","Premi **Programma per …** (all'ora indicata nella scheda) oppure **Pubblica ora**, e conferma."]},{h:"Tutto il piano in un colpo"},{p:"Nel piano editoriale il pulsante **Programma il piano** mette in coda tutte le schede approvate con data e ora. Prima di confermare mostra cosa è pronto e cosa no (manca la foto, data passata, profilo non collegato…)."},{h:"Controlli automatici"},{list:["Formato giusto per ogni social (es. il reel richiede un video, il carosello da 2 a 10 file).","Durata e proporzioni dei video; i video non adatti vengono convertiti da 2Target prima dell'uscita.","Lunghezza dei testi e numero di hashtag.","Con TikTok si confermano ogni volta visibilità e interazioni: lo chiede TikTok."]},{warn:"Se un post non esce, ricevi un'email (e una notifica sul telefono, se attiva) e lo trovi in «Oggi» tra le cose da sistemare. Con **Riprova** 2Target controlla prima il profilo e non ripubblica se il post è già uscito."},{tip:"Finché la pubblicazione reale non è attivata in Impostazioni, 2Target lavora in **simulazione**: fa tutti i controlli ma non pubblica davvero. Utile per provare."}],related:["canali","piano-editoriale","notifiche"]},{slug:"notifiche",title:"Notifiche sul telefono",category:"inizia",icon:"solar:bell-bing-bold-duotone",summary:"Ricevere sul telefono lead nuovi, post non usciti e problemi, anche con l'app chiusa.",audience:"team",open:{path:"/profilo",label:"Apri il Profilo"},keywords:["notifica","push","telefono","iphone","android","avvisi","installare","app","schermata home"],blocks:[{p:"Le notifiche si aggiungono alle email: arrivano subito, anche con 2Target chiusa. Si attivano su ogni dispositivo che usi."},{h:"Su Android e sul computer"},{steps:["Apri 2Target con Chrome, Edge o Firefox.","Vai in **Profilo** → **Notifiche sul telefono** → **Attiva su questo dispositivo**.","Consenti le notifiche quando il browser lo chiede.","Premi **Manda una prova** per controllare."]},{h:"Su iPhone"},{steps:["Apri 2Target con **Safari**.","Tocca **Condividi** (il quadrato con la freccia) → **Aggiungi alla schermata Home**.","Apri 2Target dalla nuova icona sulla schermata Home.","Vai in **Profilo** → **Attiva su questo dispositivo** e consenti."]},{tip:"Se hai bloccato le notifiche per sbaglio, riattivale dalle impostazioni del sito nel browser (l'icona del lucchetto accanto all'indirizzo) o, su iPhone, da Impostazioni → Notifiche → 2Target."}],related:["primi-passi"]},{slug:"funzioni",title:"Accendere e spegnere le funzioni",category:"amministrazione",icon:"solar:settings-bold",summary:"Togliere dai menu ciò che non usi, per tutti o solo per un cliente.",audience:"team",keywords:["semplificare","nascondere","menu","interruttori","disattivare","spegnere"],blocks:[{p:"2Target fa molte cose: se alcune non ti servono, spegnile. Spariscono dai menu e dalle schede; i dati restano e tornano quando le riaccendi."},{h:"Per tutti"},{steps:["Vai in **Impostazioni** → **Funzioni** (serve un amministratore).","Spegni le voci che non usate, per esempio Concorrenti o Sponsorizzate.","Premi **Salva**: i menu si aggiornano subito per tutti."]},{h:"Solo per un cliente"},{steps:["Apri il cliente → **Panoramica**.","In fondo, nel riquadro **Funzioni per questo cliente**, spegni le sezioni che con lui non usate.","Premi **Salva**."]},{p:"Restano sempre accesi Panoramica, Piano editoriale, KPI e Canali: sono il cuore del lavoro."}],related:["impostazioni"]},{slug:"stato-del-sistema",title:"Stato del sistema e backup",category:"amministrazione",icon:"solar:shield-check-bold",summary:"Il semaforo di 2Target, gli avvisi automatici e i backup del database.",audience:"admin",open:{path:"/impostazioni#sistema",label:"Apri lo stato"},keywords:["backup","ripristino","salute","monitoraggio","scheduler","disco","errori","uptime"],blocks:[{p:"In **Impostazioni** → **Stato del sistema** trovi un semaforo per ogni parte importante: pubblicazioni programmate, coda dei post, aggiornamento notturno, backup, errori e spazio su disco."},{list:["**Verde**: tutto a posto.","**Giallo**: da guardare quando puoi.","**Rosso**: da sistemare. Gli amministratori ricevono un'email (e una notifica) al massimo ogni 12 ore per lo stesso problema."]},{h:"Backup"},{p:"Ogni notte alle 2 2Target salva una copia completa del database in una cartella privata del server. Tiene gli ultimi 7 giorni, 4 settimane e 6 mesi. Con **Esegui backup ora** ne fai uno subito (utile prima di grandi modifiche)."},{warn:"Il ripristino di un backup sostituisce i dati attuali: va fatto da un tecnico, con l'app ferma."},{tip:"Per sapere subito se 2Target si ferma, si può collegare un servizio di monitoraggio esterno (es. UptimeRobot) all'indirizzo /api/stato: risponde «503» se qualcosa non va."}],related:["impostazioni","problemi-frequenti"]},{slug:"concorrenti",title:"Confronto con i concorrenti",category:"clienti",icon:"solar:cup-star-bold",summary:"Seguire i concorrenti su Instagram e capire dove il cliente può migliorare.",audience:"team",open:{clientTab:"concorrenti",label:"Concorrenti"},keywords:["competitor","benchmark","instagram","confronto","engagement"],blocks:[{p:"Per ogni concorrente con un profilo Instagram professionale, 2Target legge ogni notte i numeri pubblici e li mette accanto a quelli del cliente: follower (con la crescita del mese), post a settimana, interazioni medie, engagement, quota di reel e data dell'ultimo post."},{steps:["Apri il cliente → **Concorrenti**.","I concorrenti trovati dal check-up sono già in elenco: aggiungi il loro profilo Instagram con la matita.","Per aggiungerne altri premi **Aggiungi** e scrivi nome e @profilo (o incolla il link).","**Aggiorna ora** rilegge subito i numeri."]},{p:"Sotto la tabella **Cosa ci dicono** riassume i punti importanti (es. «il cliente pubblica meno della metà») e **I loro post migliori** porta ai contenuti che funzionano nel settore."},{warn:"Si leggono solo profili professionali (aziendali o creator). Serve almeno un profilo Instagram collegato a 2Target tramite una Pagina Facebook, che fa da «lente»."}],related:["check-up","kpi"]},{slug:"report-mensile",title:"Report mensile al cliente",category:"risultati",icon:"solar:file-text-bold",summary:"Il riepilogo del mese in email, la pagina da stampare in PDF e il video per le storie.",audience:"team",keywords:["report","pdf","video","mese","cliente","email","stampa"],blocks:[{p:"Il report mensile racconta al cliente com'è andato il mese: follower, copertura, post usciti, contatti arrivati e obiettivi (KPI) con il semaforo."},{steps:["Apri il cliente → **Panoramica** → riquadro **Report, avvisi e approvazione**.","Accendi **Report mensile automatico al cliente** e scrivi la sua email.","Premi **Salva**. Con **Anteprima** lo vedi prima; con **Inviami una prova** lo ricevi tu."]},{p:"Il report parte da solo il 3 di ogni mese con i dati del mese chiuso. Da **Report del mese** → **Apri (PDF e video)** apri la pagina del mese scelto: si stampa in PDF e contiene un video verticale da condividere nelle storie."},{tip:"Nello stesso riquadro **Avvisa il cliente quando un post esce** gli manda il link di ogni post appena pubblicato."}],related:["kpi","lead"]},{slug:"integrazioni",title:"Chiavi delle integrazioni",category:"amministrazione",icon:"solar:shield-keyhole-bold-duotone",summary:"Dove si inseriscono le chiavi delle app di Meta, Google, TikTok, LinkedIn, Threads e Pinterest.",audience:"admin",open:{path:"/impostazioni#integrazioni",label:"Apri le integrazioni"},keywords:["chiavi","app id","secret","client id","meta for developers","google cloud","callback","reindirizzamento"],blocks:[{p:"Perché i consulenti possano collegare i social dei clienti, 2Target deve conoscere le chiavi delle app Golduck registrate presso ogni piattaforma. Si inseriscono una volta in **Impostazioni** → **Integrazioni** e si salvano cifrate."},{steps:["Apri il riquadro della piattaforma: c'è scritto dove trovare ogni chiave.","Copia l'**indirizzo di reindirizzamento** mostrato e incollalo nella console della piattaforma.","Incolla le chiavi nei campi e premi **Salva integrazioni**."]},{warn:"Le chiavi segrete non vengono più mostrate dopo il salvataggio: per cambiarle scrivi quella nuova; lasciando il campo vuoto resta quella di prima."},{tip:"La pubblicazione di YouTube Shorts resta spenta finché Google non ha verificato l'app: dopo la verifica scrivi «true» nel campo apposito e ricollega gli account Google dei clienti."}],related:["canali","impostazioni"]},{slug:"problemi-collegamento",title:"Un collegamento non funziona",category:"problemi",icon:"solar:danger-triangle-bold",summary:"Cosa fare quando un profilo è «da ricollegare» o i dati non si aggiornano.",audience:"team",keywords:["errore","scaduto","token","ricollegare","dati vecchi","non aggiorna","permessi"],blocks:[{list:["**«Da ricollegare»**: l'accesso è scaduto o è stato revocato (cambio password, permesso tolto). Vai in **Canali** e premi di nuovo **Collega** per quella piattaforma.","**«Collegato senza permesso di pubblicare»**: in fase di accesso non è stato concesso il permesso di pubblicazione. Ricollega e lascia tutte le spunte.","**Dati fermi**: i dati si aggiornano ogni notte; per averli subito premi **Aggiorna tutti i dati** (o **Aggiorna ora** sul singolo canale) nella scheda Canali.","**Profilo già collegato a un altro cliente**: un profilo appartiene a un solo cliente. Scollegalo prima dall'altro, se era un errore."]},{tip:"Ogni errore resta registrato nel **Registro attività** (categoria Errori) con i dettagli tecnici, utili se serve l'aiuto di un tecnico."}],related:["canali"]}]],178984),a.s(["articlesFor",0,function(a,b){let c="superadmin"===b||"admin"===b;return a.filter(a=>"tutti"===a.audience||"team"===a.audience&&"viewer"!==b||"admin"===a.audience&&c)}],549552)}];

